using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.AI;
using UnityEditor;
using UnityEditor.SceneManagement;
using Skybreak.World;
using Skybreak.Descent;
public static class CaptureFinalTeleportVisual
{
    static string Dir=>Path.Combine(Path.GetDirectoryName(Application.dataPath),"Docs/GV/LevelDesign/Reports/FinalTeleportPoint");
    static void Capture(Camera cam,string name){var old=RenderTexture.active;var rt=new RenderTexture(1440,1100,24);var img=new Texture2D(1440,1100,TextureFormat.RGB24,false);try{cam.targetTexture=rt;cam.aspect=1440f/1100;cam.Render();RenderTexture.active=rt;img.ReadPixels(new Rect(0,0,1440,1100),0,0);img.Apply();File.WriteAllBytes(Path.Combine(Dir,name+".png"),img.EncodeToPNG());}finally{cam.targetTexture=null;RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(img);}}
    static void Views(string prefix){Directory.CreateDirectory(Dir);var go=new GameObject("Temporary final teleport visual camera");var cam=go.AddComponent<Camera>();cam.fieldOfView=52;cam.nearClipPlane=.1f;cam.farClipPlane=300;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.02f,.045f,.06f);try{cam.transform.position=new Vector3(42,3.3f,87.5f);cam.transform.LookAt(new Vector3(42,3.2f,95.4f));Capture(cam,prefix+"Front");cam.transform.position=new Vector3(46.3f,3.6f,87.8f);cam.transform.LookAt(new Vector3(42,3.3f,95.4f));Capture(cam,prefix+"Angle");}finally{UnityEngine.Object.DestroyImmediate(go);}}
    public static string Preview(){if(EditorApplication.isPlaying||Lightmapping.isRunning)throw new Exception("Use Edit Mode outside a bake");Views("Portal");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Actual Unity portal preview saved.";}
    public static string Main(){
        if(EditorApplication.isPlaying||Lightmapping.isRunning)throw new Exception("Finish bake in Edit Mode");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/GameLevel/SkybreakMain.unity")throw new Exception("Wrong scene");
        var visual=UnityEngine.Object.FindAnyObjectByType<FinalTeleportVisual>();if(visual==null)throw new Exception("Visual controller missing");var so=new SerializedObject(visual);var field=(Renderer)so.FindProperty("energyField").objectReferenceValue;var crystal=(Renderer)so.FindProperty("crystal").objectReferenceValue;
        if(field==null||crystal==null||field.sharedMaterial.shader.name!="Skybreak/Final Teleport Field"||ShaderUtil.ShaderHasError(field.sharedMaterial.shader))throw new Exception("Field references or shader invalid");
        if(field.GetComponentsInChildren<Collider>().Length>0||field.GetComponent<MeshFilter>().sharedMesh.triangles.Length!=6||GameObjectUtility.AreStaticEditorFlagsSet(field.gameObject,StaticEditorFlags.ContributeGI))throw new Exception("Energy field geometry/setup invalid");
        var maps=LightmapSettings.lightmaps;if(maps.Length==0||maps.Any(m=>m.lightmapColor==null)||crystal.lightmapIndex<0||crystal.lightmapIndex>=maps.Length)throw new Exception("Crystal bake missing");if(NavMesh.CalculateTriangulation().indices.Length/3!=765)throw new Exception("Navigation changed");
        var roots=scene.GetRootGameObjects();var transforms=roots.SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();var renderers=transforms.SelectMany(t=>t.GetComponents<MeshRenderer>()).ToArray();if(transforms.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))>0||renderers.Any(r=>r.sharedMaterials.Any(m=>m==null)||r.GetComponent<MeshFilter>()==null||r.GetComponent<MeshFilter>().sharedMesh==null))throw new Exception("Missing references");
        var lights=transforms.SelectMany(t=>t.GetComponents<Light>()).ToArray();int baked=lights.Count(l=>l.lightmapBakeType==LightmapBakeType.Baked),mixed=lights.Count(l=>l.lightmapBakeType==LightmapBakeType.Mixed),realtime=lights.Count(l=>l.lightmapBakeType==LightmapBakeType.Realtime);int mapped=renderers.Count(r=>r.lightmapIndex>=0&&r.lightmapIndex<maps.Length);if(baked!=87||mixed!=1||realtime!=0||LightmapSettings.lightProbes.count!=506)throw new Exception("Lighting configuration changed unexpectedly");
        var preview=Preview();AssetDatabase.SaveAssets();var report="Final large crystal uses dedicated shiny cyan emission and baked light spill.\nTransparent rippling two-triangle field sits behind the crystal and inside the arch; no collider, GI contribution, shadows or depth writes.\nField shader compiled without errors. Original shrine geometry/materials preserved except the large crystal's dedicated material.\nBake: "+maps.Length+" atlases / "+LightmapSettings.lightProbes.count+" probes / "+mapped+" mapped renderers.\nLights: "+baked+" Baked / "+mixed+" Mixed / "+realtime+" realtime-only.\nExisting 765-triangle navigation unchanged. Missing scripts, meshes and materials: zero.\n"+preview+"\nSaved in Edit Mode; not committed or pushed.\nVisual only: game-end activation/teleport logic remains a later integration.";File.WriteAllText(Path.Combine(Dir,"Verification.txt"),report);return report;
    }
    [Serializable] class Pose {public Vector3 p;public Quaternion q;public bool background;}
    static DescentCharacterController Player()=>UnityEngine.Object.FindAnyObjectByType<DescentCharacterController>();
    static void Move(Vector3 p){var player=Player();var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(p,Quaternion.identity);cc.enabled=true;Physics.SyncTransforms();}
    public static string StageFar(){
        if(!Application.isPlaying)throw new Exception("Use Play Mode");var player=Player();SessionState.SetString("Skybreak.FinalTeleport.PreTestPose",JsonUtility.ToJson(new Pose{p=player.transform.position,q=player.transform.rotation,background=Application.runInBackground}));Application.runInBackground=true;Move(new Vector3(42,.04f,80));return "Arc placed 15.4m away to verify idle energy.";
    }
    public static string FarThenNear(){
        var visual=UnityEngine.Object.FindAnyObjectByType<FinalTeleportVisual>();if(visual.ApproachStrength>.02f)throw new Exception("Far response is not idle");var so=new SerializedObject(visual);var field=(Renderer)so.FindProperty("energyField").objectReferenceValue;var block=new MaterialPropertyBlock();field.GetPropertyBlock(block);float energy=block.GetFloat("_Energy");if(Mathf.Abs(energy-.6f)>.02f)throw new Exception("Idle energy wrong");Views("Idle");File.WriteAllText(Path.Combine(Dir,"RuntimeChecks.txt"),"Far (15.4m): approach strength "+visual.ApproachStrength+", field energy "+energy+".\n");Move(new Vector3(42,.04f,92));return "Idle response passed; Arc now 3.4m away for activation response.";
    }
    public static string CheckNearAndRestore(){
        var visual=UnityEngine.Object.FindAnyObjectByType<FinalTeleportVisual>();if(visual.ApproachStrength<.98f)throw new Exception("Near response has not reached full strength");var so=new SerializedObject(visual);var field=(Renderer)so.FindProperty("energyField").objectReferenceValue;var crystal=(Renderer)so.FindProperty("crystal").objectReferenceValue;var block=new MaterialPropertyBlock();field.GetPropertyBlock(block);float energy=block.GetFloat("_Energy");if(Mathf.Abs(energy-1.15f)>.02f)throw new Exception("Near energy wrong");crystal.GetPropertyBlock(block);var emission=block.GetColor("_EmissionColor");Views("Near");visual.SetPowered(false);if(field.enabled)throw new Exception("Power-off hook did not hide field");visual.SetPowered(true);if(!field.enabled)throw new Exception("Power-on hook did not restore field");File.AppendAllText(Path.Combine(Dir,"RuntimeChecks.txt"),"Near (3.4m): approach strength "+visual.ApproachStrength+", field energy "+energy+", pulsing crystal emission "+emission+".\nSetPowered(false/true) disables/restores the field. No teleport, damage or end-game action triggered.\n");
        var pose=JsonUtility.FromJson<Pose>(SessionState.GetString("Skybreak.FinalTeleport.PreTestPose",""));Move(pose.p);Player().transform.rotation=pose.q;Player().UpdateCamera(1);Application.runInBackground=pose.background;SessionState.EraseString("Skybreak.FinalTeleport.PreTestPose");return "Near response and power hooks passed. Arc pose and background setting restored.";
    }
}
